import java.util.*;

public class Phutball {
    static final int H = 15, W = 19;
    static final int[] dy = {-1, -1, -1, 0, 0, 1, 1, 1};
    static final int[] dx = {-1, 0, 1, -1, 1, -1, 0, 1};

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[][] board = new int[H][W];
        int sy = -1, sx = -1;
        List<int[]> blacks = new ArrayList<>();

        for (int y = 0; y < H; y++) {
            String line = sc.nextLine();
            for (int x = 0; x < W; x++) {
                char c = line.charAt(x);
                if (c == 'W') {
                    sy = y; sx = x;
                    board[y][x] = 0; // white stone position is empty for black stones
                } else if (c == 'B') {
                    board[y][x] = 1;
                    blacks.add(new int[]{y, x});
                } else {
                    board[y][x] = 0;
                }
            }
        }
        sc.close();

        // BFS over states: (whiteY, whiteX, bitmask of removed black stones)
        int n = blacks.size();
        int totalStates = H * W * (1 << n);
        int[][][] dist = new int[H][W][1 << n];
        for (int y = 0; y < H; y++)
            for (int x = 0; x < W; x++)
                Arrays.fill(dist[y][x], Integer.MAX_VALUE);

        int startMask = 0;
        dist[sy][sx][startMask] = 0;
        Queue<int[]> q = new ArrayDeque<>();
        q.add(new int[]{sy, sx, startMask});

        int answer = -1;

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int y = cur[0], x = cur[1], mask = cur[2];
            int d = dist[y][x][mask];

            // Check if we reached goal (bottom edge or beyond)
            if (y == H - 1) {
                answer = d;
                break;
            }

            // Try all 8 directions for jumps
            for (int dir = 0; dir < 8; dir++) {
                int ny = y + dy[dir];
                int nx = x + dx[dir];

                // Must have an adjacent black stone to jump over
                if (ny < 0 || ny >= H || nx < 0 || nx >= W) continue;

                // Find which black stone is at (ny, nx) and not yet removed
                int idx = -1;
                for (int i = 0; i < n; i++) {
                    if ((mask & (1 << i)) == 0 && blacks.get(i)[0] == ny && blacks.get(i)[1] == nx) {
                        idx = i;
                        break;
                    }
                }
                if (idx == -1) continue; // no black stone there or already removed

                // Now jump: keep jumping in same direction as long as we land on black stones
                int curY = y, curX = x;
                int newMask = mask;
                boolean valid = true;
                int jumpCount = 0;

                while (true) {
                    int nextY = curY + dy[dir];
                    int nextX = curX + dx[dir];

                    // Check bounds
                    if (nextY < 0 || nextY >= H || nextX < 0 || nextX >= W) {
                        // Jumped off board? According to problem, white stone must be on goal or still on board.
                        // If we jump off the bottom edge (y >= H), that counts as reaching goal.
                        // But if we jump off other edges, it's invalid.
                        if (nextY >= H) {
                            // Reached goal via jumping off bottom
                            answer = d + 1;
                            System.out.println(answer);
                            return;
                        } else {
                            valid = false;
                        }
                        break;
                    }

                    // Check if landing on a black stone
                    int landIdx = -1;
                    for (int i = 0; i < n; i++) {
                        if ((newMask & (1 << i)) == 0 && blacks.get(i)[0] == nextY && blacks.get(i)[1] == nextX) {
                            landIdx = i;
                            break;
                        }
                    }

                    if (landIdx != -1) {
                        // Land on black stone, remove it and continue jumping
                        newMask |= (1 << landIdx);
                        curY = nextY;
                        curX = nextX;
                        jumpCount++;
                        continue;
                    } else {
                        // Landed on empty cell
                        // Check if this cell is the white stone's original position? 
                        // Actually white stone moves, so it's fine as long as no black stone there.
                        // Also check if it's the goal (bottom edge)
                        if (nextY == H - 1) {
                            answer = d + 1;
                            System.out.println(answer);
                            return;
                        }

                        // If we haven't moved at least one step, invalid
                        if (jumpCount == 0) {
                            valid = false;
                            break;
                        }

                        // New state
                        if (dist[nextY][nextX][newMask] > d + 1) {
                            dist[nextY][nextX][newMask] = d + 1;
                            q.add(new int[]{nextY, nextX, newMask});
                        }
                        break;
                    }
                }
            }
        }

        System.out.println(answer);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static final int W = 19;
    static final int H = 15;

    static int sx, sy;
    static boolean[][] initBlack = new boolean[H][W];
    static int best = Integer.MAX_VALUE;

    static final int[] dx = {-1, -1, -1, 0, 0, 1, 1, 1};
    static final int[] dy = {-1, 0, 1, -1, 1, -1, 0, 1};

    static void dfs(int x, int y, boolean[][] black, int jumps) {
        if (jumps >= best) return;

        for (int dir = 0; dir < 8; dir++) {
            int nx = x + dx[dir];
            int ny = y + dy[dir];

            if (!inside(nx, ny) || !black[ny][nx]) continue; // adjacent must be black

            int tx = nx;
            int ty = ny;
            int cnt = 0;
            while (inside(tx, ty) && black[ty][tx]) {
                tx += dx[dir];
                ty += dy[dir];
                cnt++;
            }

            // must jump over one or more consecutive black stones and land on empty square or goal(below board)
            if (ty > H - 1) { // reached below bottom edge => goal
                best = Math.min(best, jumps + 1);
                continue;
            }

            if (!inside(tx, ty)) continue; // out from left/right/top is invalid
            if (black[ty][tx]) continue;   // landing square must not be black (normally impossible here)

            // perform jump: remove jumped stones
            boolean[][] next = copyBoard(black);
            int rx = x + dx[dir];
            int ry = y + dy[dir];
            for (int i = 0; i < cnt; i++) {
                next[ry][rx] = false;
                rx += dx[dir];
                ry += dy[dir];
            }

            dfs(tx, ty, next, jumps + 1);
        }
    }

    static boolean inside(int x, int y) {
        return 0 <= x && x < W && 0 <= y && y < H;
    }

    static boolean[][] copyBoard(boolean[][] b) {
        boolean[][] c = new boolean[H][W];
        for (int i = 0; i < H; i++) c[i] = b[i].clone();
        return c;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> lines = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) {
            if (!line.isEmpty() || lines.size() < H) lines.add(line);
        }

        // Expect 15 lines of 19 chars.
        for (int y = 0; y < H; y++) {
            String s = lines.get(y);
            for (int x = 0; x < W; x++) {
                char ch = s.charAt(x);
                if (ch == 'O' || ch == 'W') {
                    sx = x;
                    sy = y;
                } else if (ch == 'X' || ch == 'B') {
                    initBlack[y][x] = true;
                }
            }
        }

        dfs(sx, sy, initBlack, 0);

        if (best == Integer.MAX_VALUE) {
            System.out.println("-1");
        } else {
            System.out.println(best);
        }
    }
}

