                }
            }
            if (!valid) continue;
            // New removed set
            bitset<285> new_removed = removed;
            new_removed[bidx] = 1;
            State new_state = {nr2 >= R ? R : nr2, nc2, new_removed};
            if (visited.find(new_state) == visited.end()) {
                visited.insert(new_state);
                q.push({nr2 >= R ? R : nr2, nc2, new_removed, dist+1});
            }
        }
    }
    cout << -1 << "\n";
    return 0;
}

