struct State {
    int pos;                  // 0..284 on board, 285 = goal
    bitset<285> black;        // black stones on the board
};

static inline int id(int r, int c) { return r * 19 + c; }

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<string> board(15);
    for (int i = 0; i < 15; ++i) {
        if (!(cin >> board[i])) return 0;
    }

    int start = -1;
    bitset<285> initBlack;
    for (int r = 0; r < 15; ++r) {
        for (int c = 0; c < 19; ++c) {
            char ch = board[r][c];
            if (ch == 'O') start = id(r, c);      // white stone
            else if (ch == 'X') initBlack.set(id(r, c)); // black stone
        }
    }

    const int GOAL = 285;
    const int dr[8] = {-1,-1,-1,0,0,1,1,1};
    const int dc[8] = {-1,0,1,-1,1,-1,0,1};

    struct Hasher {
        size_t operator()(State const& s) const {
            size_t h = std::hash<int>()(s.pos);
            const unsigned long long* p =
                reinterpret_cast<const unsigned long long*>(&s.black);
            size_t cnt = sizeof(s.black) / sizeof(unsigned long long);
            for (size_t i = 0; i < cnt; ++i) {
                h ^= std::hash<unsigned long long>()(p[i] + 0x9e3779b97f4a7c15ULL + (h << 6) + (h >> 2));
            }
            return h;
        }
    };
    struct Eq {
        bool operator()(State const& a, State const& b) const {
            return a.pos == b.pos && a.black == b.black;
        }
    };

    queue<pair<State,int>> q;
    unordered_set<State, Hasher, Eq> vis;

    State init{start, initBlack};
    q.push({init, 0});
    vis.insert(init);

    while (!q.empty()) {
        auto [cur, dist] = q.front();
        q.pop();

        if (cur.pos == GOAL) {
            cout << dist << '\n';
            return 0;
        }

        int r = cur.pos / 19;
        int c = cur.pos % 19;

        for (int d = 0; d < 8; ++d) {
            int nr = r + dr[d], nc = c + dc[d];
            if (nr < 0 || nr >= 15 || nc < 0 || nc >= 19) continue;

            int first = id(nr, nc);
            if (!cur.black.test(first)) continue; // adjacent cell must have black stone

            // Count consecutive black stones in this direction
            int tr = nr, tc = nc, k = 0;
            while (tr >= 0 && tr < 15 && tc >= 0 && tc < 19 && cur.black.test(id(tr, tc))) {
                ++k;
                tr += dr[d];
                tc += dc[d];
            }

            // Landing cell after exactly k stones
            int lr = r + dr[d] * (k + 1);
            int lc = c + dc[d] * (k + 1);

            // Goal is bottom edge or below it
            if (dr[d] == 1 && lr >= 15) {
                State nxt = cur;
                nxt.pos = GOAL;
                for (int i = 1; i <= k; ++i) {
                    int rr = r + dr[d] * i;
                    int cc = c + dc[d] * i;
                    nxt.black.reset(id(rr, cc));
                }
                if (!vis.count(nxt)) {
                    vis.insert(nxt);
                    q.push({nxt, dist + 1});
                }
                continue;
            }

            // Otherwise landing position must remain on board
            if (lr < 0 || lr >= 15 || lc < 0 || lc >= 19) continue;

            int land = id(lr, lc);
            if (cur.black.test(land)) continue; // cannot land on black stone

            State nxt = cur;
            nxt.pos = land;
            for (int i = 1; i <= k; ++i) {
                int rr = r + dr[d] * i;
                int cc = c + dc[d] * i;
                nxt.black.reset(id(rr, cc));
            }

            if (!vis.count(nxt)) {
                vis.insert(nxt);
                q.push({nxt, dist + 1});
            }
        }
    }

    cout << -1 << '\n';
    return 0;
}

