#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define W 19
#define H 15
#define N (W * H)
#define MAXB 64

typedef struct {
    int wx, wy;
    unsigned long long mask;
    int dist;
} Node;

typedef struct Entry {
    unsigned long long mask;
    unsigned short pos;
    struct Entry *next;
} Entry;

static int dx[8] = {-1, 0, 1, -1, 1, -1, 0, 1};
static int dy[8] = {-1, -1, -1, 0, 0, 1, 1, 1};

static int id(int x, int y) { return y * W + x; }

int main(void) {
    char board[H][W + 5];
    int x, y, i, d;

    for (y = 0; y < H; y++) {
        if (scanf("%s", board[y]) != 1) return 0;
    }

    int wx = -1, wy = -1;
    int bx[MAXB], by[MAXB], bcnt = 0;

    for (y = 0; y < H; y++) {
        for (x = 0; x < W; x++) {
            char c = board[y][x];
            if (c == 'O' || c == 'W') {
                wx = x; wy = y;
            } else if (c == 'X' || c == 'B') {
                bx[bcnt] = x;
                by[bcnt] = y;
                bcnt++;
            }
        }
    }

    if (wx < 0 || bcnt > MAXB) {
        puts("-1");
        return 0;
    }

    int blackIndex[N];
    for (i = 0; i < N; i++) blackIndex[i] = -1;
    for (i = 0; i < bcnt; i++) blackIndex[id(bx[i], by[i])] = i;

    unsigned long long startMask = 0ULL;
    for (i = 0; i < bcnt; i++) startMask |= (1ULL << i);

    size_t qcap = 1 << 20;
    Node *queue = (Node *)malloc(sizeof(Node) * qcap);
    if (!queue) return 0;
    size_t head = 0, tail = 0;

    size_t hsize = 1 << 22;
    Entry **hash = (Entry **)calloc(hsize, sizeof(Entry *));
    if (!hash) return 0;

    #define HASH(mask,pos) (((unsigned int)((mask) ^ ((mask)>>32) ^ (pos) * 1000003u)) & (hsize - 1))

    queue[tail++] = (Node){wx, wy, startMask, 0};

    {
        unsigned short pos = (unsigned short)id(wx, wy);
        unsigned int h = HASH(startMask, pos);
        Entry *e = (Entry *)malloc(sizeof(Entry));
        e->mask = startMask;
        e->pos = pos;
        e->next = hash[h];
        hash[h] = e;
    }

    while (head < tail) {
        Node cur = queue[head++];

        for (d = 0; d < 8; d++) {
            int nx = cur.wx + dx[d];
            int ny = cur.wy + dy[d];

            if (nx < 0 || nx >= W || ny < 0 || ny >= H) continue;

            int first = blackIndex[id(nx, ny)];
            if (first < 0) continue;
            if (((cur.mask >> first) & 1ULL) == 0) continue;

            int cx = nx, cy = ny, len = 0;
            while (cx >= 0 && cx < W && cy >= 0 && cy < H) {
                int bi = blackIndex[id(cx, cy)];
                if (bi >= 0 && ((cur.mask >> bi) & 1ULL)) {
                    len++;
                    cx += dx[d];
                    cy += dy[d];
                } else break;
            }

            if (len == 0) continue;

            int tx = cur.wx + dx[d] * (len + 1);
            int ty = cur.wy + dy[d] * (len + 1);

            if (ty >= H) {
                printf("%d\n", cur.dist + 1);
                return 0;
            }

            if (tx < 0 || tx >= W || ty < 0 || ty >= H) continue;

            {
                int bi = blackIndex[id(tx, ty)];
                if (bi >= 0 && ((cur.mask >> bi) & 1ULL)) continue;
            }

            unsigned long long nmask = cur.mask;
            cx = nx; cy = ny;
            while (cx != tx || cy != ty) {
                int bi = blackIndex[id(cx, cy)];
                if (bi >= 0 && ((nmask >> bi) & 1ULL)) nmask &= ~(1ULL << bi);
                cx += dx[d];
                cy += dy[d];
            }

            unsigned short pos = (unsigned short)id(tx, ty);
            unsigned int h = HASH(nmask, pos);
            Entry *e = hash[h];
            int seen = 0;
            while (e) {
                if (e->mask == nmask && e->pos == pos) {
                    seen = 1;
                    break;
                }
                e = e->next;
            }
            if (seen) continue;

            e = (Entry *)malloc(sizeof(Entry));
            e->mask = nmask;
            e->pos = pos;
            e->next = hash[h];
            hash[h] = e;

            if (tail >= qcap) {
                qcap <<= 1;
                queue = (Node *)realloc(queue, sizeof(Node) * qcap);
                if (!queue) return 0;
            }
            queue[tail++] = (Node){tx, ty, nmask, cur.dist + 1};
        }
    }

